mapper.update:
update aem_exam_invigilation
exam_id = #{examId}, classroom_id = #{classroomId}, teacher_id = #{teacherId}, exam_date = #{examDate}, start_time = #{startTime}, end_time = #{endTime}, duty_type = #{dutyType}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where invigilation_id = #{invigilationId}

mapper.select:
select count(1) from aem_exam_invigilation
where teacher_id = #{teacherId}
  and exam_date = #{examDate}
  and status = '0'
  and exam_id != #{excludeExamId}
  and (
      (start_time <= #{startTime} and end_time > #{startTime})
      or (start_time < #{endTime} and end_time >= #{endTime})
      or (start_time >= #{startTime} and end_time <= #{endTime})
  )

select distinct teacher_id from aem_exam_invigilation
where exam_date = #{examDate}
  and status = '0'
  and exam_id != #{excludeExamId}
  and (
      (start_time <= #{startTime} and end_time > #{startTime})
      or (start_time < #{endTime} and end_time >= #{endTime})
      or (start_time >= #{startTime} and end_time <= #{endTime})
  )

select distinct o.teacher_id
from tpm_course_offering o
where o.del_flag = '0'
  and o.teacher_id is not null
  and o.course_id = #{courseId}
  and o.semester_id = #{semesterId}
